S['NONG1711A'] = [{'k': 'noti', 'ch': 'Mở đầu', 'cap': ('LÃI SUẤT TIẾT KIỆM 0%', 'TỪ NGÀY 16/11'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '07:40', 'ngay': 'Thứ Hai', 'items': [('Tin tức', 'Ngân hàng', 'SCB đưa lãi suất tiết kiệm online về 0% cho các kỳ hạn từ 31 ngày đến 36 tháng', (239, 68, 68)), ('Con gái', 'Tin nhắn', 'Mẹ ơi, sổ 200 triệu của mẹ ở SCB tuần này đáo hạn đúng không?', (56, 189, 248))]}, 'say': 'Bảy giờ bốn mươi sáng thứ Hai, cô Hạnh, giáo viên đã nghỉ hưu, đọc được một tin hiếm thấy. Từ ngày mười sáu tháng mười một, ngân hàng SCB đưa lãi suất tiết kiệm online về không phần trăm, cho các kỳ hạn từ ba mươi mốt ngày đến ba mươi sáu tháng. Một phút sau, con gái nhắn: mẹ ơi, sổ hai trăm triệu của mẹ ở SCB tuần này đáo hạn đúng không?'}, {'k': 'bignum', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('GỬI 200 TRIỆU 6 THÁNG', 'NHẬN 0 ĐỒNG TIỀN LÃI'), 'cols': ((255, 255, 255), (239, 68, 68)), 'value': 0, 'fmt': '{:,.0f}', 'unit': ' đồng', 'top': 'LÃI 200 TRIỆU GỬI 6 THÁNG', 'sub': 'Biểu lãi suất SCB từ 16/11/2026', 'col': (239, 68, 68), 'say': 'Nếu cô gửi lại hai trăm triệu, kỳ hạn sáu tháng, theo biểu mới, tiền lãi là không đồng. Ngân hàng nhận tiền mà không trả lãi, chuyện đó nghĩa là gì? Tiền của người gửi có còn an toàn không? Và nếu là anh chị, anh chị sẽ làm gì với cuốn sổ sắp đáo hạn?'}, {'k': 'giay', 'ch': 'Chương 1 – Biểu lãi suất mới nói gì?', 'cap': ('BIỂU LÃI SUẤT MỚI', 'CHỈ CÒN 2 KỲ HẠN CÓ LÃI'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'BIỂU LÃI SUẤT SCB TỪ 16/11', 'so': 'Theo Dân trí và Người Quan Sát, 16/11/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Tiết kiệm online 31 ngày đến 36 tháng: 0%.', '0%'), ('Tại quầy, khách gửi mới, 1 đến 11 tháng: 0%.', '0%'), ('Kỳ hạn 12 tháng: 3,7% mỗi năm.', '3,7%'), ('Kỳ hạn 13 tháng: 8,7% mỗi năm, lãi cuối kỳ.', 'CÓ ĐIỀU KIỆN?')]}, 'say': 'Con gái gửi sang bảng tóm tắt theo báo Dân trí và Người Quan Sát. Một, tiết kiệm online, từ ba mươi mốt ngày đến ba mươi sáu tháng, đều không phần trăm. Hai, tại quầy, khách cá nhân gửi mới, kỳ hạn dưới mười hai tháng cũng không phần trăm. Ba, chỉ còn kỳ hạn mười hai tháng là ba phẩy bảy phần trăm mỗi năm. Bốn, kỳ hạn mười ba tháng ghi tám phẩy bảy phần trăm, lãi cuối kỳ.'}, {'k': 'giay', 'cap': ('BIỂU LÃI SUẤT MỚI', 'CHỈ CÒN 2 KỲ HẠN CÓ LÃI'), 'cols': ((255, 255, 255), (239, 68, 68)), 'giay': {'tieu_de': 'BIỂU LÃI SUẤT SCB TỪ 16/11', 'so': 'Theo Dân trí và Người Quan Sát, 16/11/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Tiết kiệm online 31 ngày đến 36 tháng: 0%.', '0%'), ('Tại quầy, khách gửi mới, 1 đến 11 tháng: 0%.', '0%'), ('Kỳ hạn 12 tháng: 3,7% mỗi năm.', '3,7%'), ('Kỳ hạn 13 tháng: 8,7% mỗi năm, lãi cuối kỳ.', 'CÓ ĐIỀU KIỆN?')]}, 'say': 'Mức cao bất thường này, theo báo, thường kèm điều kiện, và ngân hàng chưa công bố biểu thay thế cho hai kỳ hạn này.'}, {'k': 'bars', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('TỪ 9,5% VỀ 0%', 'TRONG HƠN 2 NĂM'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('Trước 2024', 9.5, (34, 197, 94), '9,5%'), ('2024 đến T9/2026', 3.9, (255, 196, 0), '3,9%'), ('Cuối T10/2026', 0.7, (239, 68, 68), '0,7%'), ('Từ 16/11/2026', 0.05, (239, 68, 68), '0%')], 'say': 'Nhìn lại lãi suất cao nhất SCB từng trả, theo báo MotTheGioi. Trước năm hai nghìn không trăm hai mươi bốn, có lúc lên tới chín phẩy năm phần trăm. Từ năm hai nghìn không trăm hai mươi bốn đến trước tháng mười năm nay, còn ba phẩy chín phần trăm. Cuối tháng mười còn không phẩy bảy phần trăm. Và từ hôm qua, về không. Đây là lần điều chỉnh mạnh thứ hai chỉ trong khoảng một tháng.'}, {'k': 'cards', 'anh': 'ov:Ben Thanh Market||Ben Thanh Market', 'cap': ('CÙNG 200 TRIỆU, 6 THÁNG', 'NƠI 0 ĐỒNG, NƠI 6,6 TRIỆU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('0 đồng', 'SCB, 6 tháng, biểu mới', 'KHÔNG CÓ LÃI'), ('700 nghìn', 'SCB, biểu cuối tháng 10', 'LÃI 0,7%'), ('6,6 triệu', 'Ngân hàng khác, 6,6% mỗi năm', 'MỨC NIÊM YẾT ONLINE')], 'say': 'Em tính thử với hai trăm triệu, kỳ hạn sáu tháng. Theo biểu mới của SCB, lãi là không đồng. Theo biểu cuối tháng mười, khoảng bảy trăm nghìn đồng. Còn ở một ngân hàng tư nhân lớn đang niêm yết sáu phẩy sáu phần trăm mỗi năm cho kỳ hạn này, cùng số tiền đó cho khoảng sáu phẩy sáu triệu đồng.'}, {'k': 'chat', 'ch': 'Chương 2 – Vì sao ngân hàng không trả lãi?', 'cap': ('"NGÂN HÀNG KHÔNG TRẢ LÃI', 'LÀ HẾT TIỀN À?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'chat': {'ten': 'Anh Toàn', 'tv': 'Đang hoạt động', 'gio': '08:15', 'mau': (34, 197, 94), 'msgs': [('me', 'Ngân hàng không trả lãi là hết tiền à cháu?'), ('Anh Toàn', 'Không hẳn cô ạ. Ngân hàng này đang được cơ cấu lại'), ('Anh Toàn', 'Họ không cần hút thêm tiền gửi mới')]}, 'say': 'Cô Hạnh nhắn cho anh Toàn, hàng xóm làm kế toán. Ngân hàng không trả lãi, có phải là hết tiền không? Anh Toàn trả lời: chưa thể nói vậy. Ngân hàng này đang trong quá trình cơ cấu lại. Ngân hàng không công bố lý do chính thức, nhưng trả lãi bằng không thì gần như là nói rằng họ không cần hút thêm tiền gửi mới.'}, {'k': 'giay', 'cap': ('KIỂM SOÁT ĐẶC BIỆT', 'TỪ THÁNG 10/2022'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'NHỮNG ĐIỀU ĐÃ CÔNG BỐ', 'so': 'Theo Dân trí 16/11/2026 và CafeF 22/8/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Kiểm soát đặc biệt từ năm 2022.', 'TỪ 2022'), ('Từ 240 điểm giao dịch, nay còn 8.', 'CÒN 8 ĐIỂM'), ('Chuyển tiền nhanh tối đa 20 triệu mỗi ngày.', '20 TRIỆU'), ('30/6/2026: trình phương án xử lý tài sản.', 'ĐANG XỬ LÝ')]}, 'say': 'Anh Toàn gửi những điều đã được công bố. Một, SCB được Ngân hàng Nhà nước đặt vào diện kiểm soát đặc biệt từ năm hai nghìn không trăm hai mươi hai, sau biến cố liên quan tập đoàn Vạn Thịnh Phát. Hai, trước đó ngân hàng có khoảng hai trăm bốn mươi điểm giao dịch, đến ngày ba tháng mười một chỉ còn tám điểm, ở sáu tỉnh, thành. Ba, hạn mức chuyển tiền nhanh trên ứng dụng giảm còn tối đa hai mươi triệu đồng mỗi ngày.'}, {'k': 'giay', 'cap': ('KIỂM SOÁT ĐẶC BIỆT', 'TỪ THÁNG 10/2022'), 'cols': ((255, 255, 255), (255, 196, 0)), 'giay': {'tieu_de': 'NHỮNG ĐIỀU ĐÃ CÔNG BỐ', 'so': 'Theo Dân trí 16/11/2026 và CafeF 22/8/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Kiểm soát đặc biệt từ năm 2022.', 'TỪ 2022'), ('Từ 240 điểm giao dịch, nay còn 8.', 'CÒN 8 ĐIỂM'), ('Chuyển tiền nhanh tối đa 20 triệu mỗi ngày.', '20 TRIỆU'), ('30/6/2026: trình phương án xử lý tài sản.', 'ĐANG XỬ LÝ')]}, 'say': 'Bốn, theo CafeF, ngày ba mươi tháng sáu năm nay, Ngân hàng Nhà nước đã trình Thủ tướng phương án xử lý tài sản thu hồi nợ của SCB.'}, {'k': 'bignum', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('CỨ 30 ĐIỂM GIAO DỊCH', 'NAY CÒN 1'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': 8, 'fmt': '{:,.0f}', 'unit': ' điểm', 'top': 'ĐIỂM GIAO DỊCH CÒN LẠI', 'sub': 'Từ khoảng 240 điểm trước năm 2022', 'col': (239, 68, 68), 'say': 'Em chia hai trăm bốn mươi cho tám, ra ba mươi. Cứ ba mươi điểm giao dịch ngày trước, nay còn một. Ngân hàng đang thu nhỏ lại, giảm chi phí, xử lý nợ xấu. Trong bối cảnh đó, lãi suất bằng không là một cách để dòng tiền gửi mới tự đi nơi khác.'}, {'k': 'cards', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('CẢ NGÀNH CŨNG GIẢM', 'NHƯNG KHÔNG VỀ 0'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('4,15 đến 6,9%', 'Lãi online 6 tháng phổ biến', 'NGÂN HÀNG KHÁC'), ('6 đến 7%', 'Lãi online 12 tháng phổ biến', 'NGÂN HÀNG KHÁC'), ('8 đến 10%', 'Trái phiếu ngân hàng', 'VẪN HUY ĐỘNG')], 'say': 'Có phải cả ngành đang về không? Không. Theo Dân trí, lãi tiết kiệm online kỳ hạn sáu tháng ở các ngân hàng khác phổ biến từ hơn bốn phần trăm đến sáu phẩy chín phần trăm. Kỳ hạn mười hai tháng từ sáu đến bảy phần trăm. Đúng là lãi đang giảm dần. Nhưng theo Vietstock, ngân hàng vẫn huy động qua trái phiếu ở mức tám đến mười phần trăm. Trường hợp SCB là cá biệt, không phải xu hướng chung.'}, {'k': 'call', 'ch': 'Chương 3 – Lần trước là tháng 10/2022', 'cap': ('"ĐÊM ĐÓ BÁC XẾP HÀNG', 'RÚT HẾT, MẤT SẠCH LÃI"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'call': {'ten': 'Bác Tư', 'phu': 'Hàng xóm, gửi tiết kiệm 20 năm', 'mau': (255, 196, 0), 'loi': ['Tháng 10/2022 bác rút trước hạn', 'Mất gần hết tiền lãi']}, 'say': 'Trưa đó cô Hạnh gọi cho bác Tư, hàng xóm gửi tiết kiệm hơn hai mươi năm. Bác kể: chiều tối mùng bảy tháng mười năm hai nghìn không trăm hai mươi hai, tin đồn về ngân hàng này lan trên mạng. Bác cũng xếp hàng, rút trước hạn cả cuốn sổ. Tiền gốc còn nguyên, nhưng gần như mất sạch tiền lãi của kỳ hạn.'}, {'k': 'giay', 'cap': ('THÁNG 10/2022', 'NHỮNG CON SỐ CỦA LẦN TRƯỚC'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'NHỮNG CON SỐ CỦA LẦN TRƯỚC', 'so': 'Theo VnEconomy 8/10/2022 và báo chí ngày 15/10/2022', 'dau': 'SO SÁNH', 'dieu': [('7/10/2022: tin đồn lan, người dân rút tiền.', 'RÚT ỒN ÀO'), ('Ngân hàng Nhà nước: quyền lợi người gửi được bảo đảm.', 'CAM KẾT'), ('12/10/2022: gửi lại gần 6.000 tỷ trong 1 ngày.', 'GỬI LẠI'), ('Người rút trước hạn: mất lãi kỳ hạn.', 'THIỆT THẬT')]}, 'say': 'Những con số của lần trước. Ngày tám tháng mười năm hai nghìn không trăm hai mươi hai, theo VnEconomy, Ngân hàng Nhà nước khẳng định quyền lợi người gửi tiền được bảo đảm. Cơ quan này cũng khuyên người dân cân nhắc, vì rút trước hạn sẽ mất lãi. Ngày mười hai tháng mười, SCB cho biết khách gửi lại gần sáu nghìn tỷ đồng chỉ trong một ngày, so với hơn một nghìn sáu trăm tỷ của ngày trước đó. Người thiệt thật là người hoảng loạn rút trước hạn.'}, {'k': 'checklist', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('GIỐNG 2, KHÁC 2', 'SO VỚI NĂM 2022'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Giống: cùng một ngân hàng', (239, 68, 68)), ('Giống: tin lan rất nhanh', (239, 68, 68)), ('Khác: không ai bị giữ tiền', (34, 197, 94)), ('Khác: bảo hiểm tiền gửi 350 triệu', (34, 197, 94))], 'say': 'So với năm hai nghìn không trăm hai mươi hai, có hai điểm giống và hai điểm khác. Giống ở chỗ cùng một ngân hàng, và tin tức lan rất nhanh. Khác ở chỗ lần này không có chuyện ngân hàng giữ tiền, chỉ là không trả lãi cho tiền gửi mới. Và lưới an toàn đã dày hơn nhiều, như em kể ngay sau đây. Chưa có biến cố, không có nghĩa là không cần để ý.'}, {'k': 'bignum', 'ch': 'Chương 4 – Lưới an toàn 350 triệu', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('BẢO HIỂM TIỀN GỬI', 'TỐI ĐA 350 TRIỆU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 350, 'fmt': '{:,.0f}', 'unit': ' triệu', 'top': 'HẠN MỨC CHI TRẢ TỪ 13/7/2026', 'sub': 'Thông tư 05/2026, gấp 2,8 lần mức cũ 125 triệu', 'col': (255, 196, 0), 'say': 'Từ ngày mười ba tháng bảy năm nay, theo quy định mới của Ngân hàng Nhà nước, hạn mức chi trả bảo hiểm tiền gửi tăng lên tối đa ba trăm năm mươi triệu đồng. Mức này gấp hai phẩy tám lần mức cũ một trăm hai mươi lăm triệu. Con số này tính trên tổng tiền gốc và lãi của một người, tại một ngân hàng.'}, {'k': 'chat', 'cap': ('"SỔ 200 TRIỆU CỦA MẸ', 'NẰM TRONG HẠN MỨC"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Con gái', 'tv': 'Đang hoạt động', 'gio': '12:30', 'mau': (34, 197, 94), 'msgs': [('Con gái', 'Sổ 200 triệu của mẹ nằm trong hạn mức 350 triệu'), ('me', 'Vậy mẹ có cần rút ngay không?'), ('Con gái', 'Đợi đúng ngày đáo hạn đã mẹ, rút trước là mất lãi')]}, 'say': 'Con gái nhắn: sổ hai trăm triệu của mẹ nằm trong hạn mức ba trăm năm mươi triệu. Cô hỏi lại: vậy có cần rút ngay không? Con gái trả lời đúng bài học của bác Tư: đợi đúng ngày đáo hạn, rút trước là mất lãi của kỳ đang gửi.'}, {'k': 'cards', 'ch': 'Chương 5 – Ba con đường cho cuốn sổ', 'anh': 'ov:Hanoi apartment buildings||Hanoi apartment buildings', 'cap': ('3 CON ĐƯỜNG', 'CHO 200 TRIỆU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('0 đồng', 'Gửi lại 6 tháng tại SCB', 'KHÔNG CÓ LÃI'), ('7,4 triệu', 'Kỳ hạn 12 tháng, lãi 3,7%', 'SAU 1 NĂM'), ('6,6 triệu', 'Nơi khác 6 tháng, lãi 6,6%', 'SAU 6 THÁNG')], 'say': 'Đến ngày đáo hạn, cô Hạnh có ba con đường. Một, gửi lại sáu tháng tại SCB, lãi không đồng. Hai, chuyển sang kỳ hạn mười hai tháng, lãi ba phẩy bảy phần trăm, sau một năm được khoảng bảy phẩy bốn triệu đồng. Ba, rút ra gửi nơi khác, với mức sáu phẩy sáu phần trăm thì sáu tháng được khoảng sáu phẩy sáu triệu đồng.'}, {'k': 'giay', 'cap': ('RÚT 200 TRIỆU', 'CHUYỂN NHANH MẤT 10 NGÀY'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'GHI CHÚ TRƯỚC NGÀY ĐÁO HẠN', 'so': 'Cô Hạnh tự ghi, số liệu theo báo 16/11/2026', 'dau': 'CẦN NHỚ', 'dieu': [('Chuyển nhanh tối đa 20 triệu mỗi ngày.', '10 NGÀY'), ('Rút tại quầy: chỉ còn 8 điểm giao dịch.', 'HỎI TRƯỚC'), ('Mang căn cước, hỏi rõ thủ tục.', 'GIẤY TỜ'), ('Lãi 13 tháng 8,7%: hỏi điều kiện.', 'ĐỌC KỸ')]}, 'say': 'Nhưng con đường thứ ba có vài điều phải biết. Hạn mức chuyển tiền nhanh là hai mươi triệu đồng mỗi ngày, hai trăm triệu sẽ mất khoảng mười ngày nếu chuyển qua ứng dụng. Rút tại quầy thì cả nước chỉ còn tám điểm giao dịch, nên gọi hỏi trước. Còn mức tám phẩy bảy phần trăm của kỳ hạn mười ba tháng, cô ghi rõ: phải hỏi điều kiện, không chạy theo con số bất thường.'}, {'k': 'chat', 'cap': ('"MẸ CHIA RA 2 NƠI', 'MỖI NƠI DƯỚI 350 TRIỆU"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Con gái', 'tv': 'Đang hoạt động', 'gio': '20:10', 'mau': (34, 197, 94), 'msgs': [('me', 'Đáo hạn mẹ rút, gửi sang chỗ có lãi'), ('me', 'Tiền hưu sau này mẹ chia ra 2 nơi'), ('Con gái', 'Mỗi nơi dưới 350 triệu là mẹ ngủ ngon')]}, 'say': 'Tối đó cô Hạnh nhắn cho con gái kế hoạch của mình. Đến ngày đáo hạn, cô sẽ rút và gửi sang nơi có lãi. Tiền dành dụm sau này, cô chia ra hai ngân hàng. Con gái trả lời: mỗi nơi dưới ba trăm năm mươi triệu là mẹ ngủ ngon. Đó là lựa chọn của cô Hạnh, không phải lời khuyên chung cho mọi người.'}, {'k': 'checklist', 'ch': 'Chương 6 – Phép thử cho sổ tiết kiệm', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('PHÉP THỬ', 'SỔ CỦA ANH CHỊ Ở ĐÂU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Gốc và lãi 1 nơi dưới 350 triệu?', (34, 197, 94)), ('Có sổ đáo hạn trong 30 ngày?', (255, 196, 0)), ('Lãi đang nhận dưới 4%?', (255, 196, 0)), ('Mức lãi cao bất thường?', (239, 68, 68))], 'say': 'Em gợi ý một phép thử tự soi. Một, tổng gốc và lãi của anh chị ở mỗi ngân hàng có dưới ba trăm năm mươi triệu đồng không. Hai, có cuốn sổ nào đáo hạn trong ba mươi ngày tới. Ba, mức lãi đang nhận có thấp hơn bốn phần trăm, trong khi mặt bằng kỳ hạn mười hai tháng đang khoảng sáu đến bảy phần trăm. Bốn, có mức lãi nào cao bất thường so với nơi khác. Đây là mốc tự soi, không phải lời khuyên.'}, {'k': 'checklist', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('3 ĐIỀU CẦN THEO DÕI', 'TỪ NAY TỚI CUỐI NĂM'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Biểu mới cho kỳ hạn 12, 13 tháng', (255, 196, 0)), ('Phương án cơ cấu lại SCB', (255, 196, 0)), ('Lãi suất nơi khác giảm tiếp?', (239, 68, 68))], 'say': 'Ba điều đáng theo dõi tới cuối năm. SCB công bố biểu mới cho kỳ hạn mười hai và mười ba tháng ra sao. Phương án cơ cấu lại ngân hàng này được quyết thế nào. Và lãi suất tiết kiệm ở các ngân hàng khác có giảm tiếp hay không. Muốn hiểu vì sao gửi tiết kiệm chưa chắc đã giữ được sức mua, anh chị có thể đọc bài miễn phí trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'chat', 'ch': 'Kết – Tin nhắn cuối ngày', 'cap': ('"TIỀN GỬI KHÔNG MẤT', 'CHỈ LÀ ĐỨNG YÊN"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Bác Tư', 'tv': 'Đang hoạt động', 'gio': '21:30', 'mau': (255, 196, 0), 'msgs': [('Bác Tư', 'Cô đừng xếp hàng như bác năm đó nhé'), ('me', 'Dạ, em đợi đáo hạn rồi tính'), ('me', 'Tiền gửi không mất, chỉ là đứng yên')]}, 'say': 'Chín giờ rưỡi tối, bác Tư nhắn: cô đừng xếp hàng như bác năm đó nhé. Cô Hạnh trả lời: dạ, em đợi đáo hạn rồi tính. Rồi cô gõ thêm một dòng: tiền gửi không mất, chỉ là đứng yên. Mà tiền đứng yên thì vẫn bị giá cả ăn mòn.'}, {'k': 'end', 'cap': ('TIỀN GỬI 1 NƠI CỦA ANH CHỊ', 'DƯỚI HAY TRÊN 350 TRIỆU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, tiền tiết kiệm của anh chị ở một ngân hàng đang dưới hay trên ba trăm năm mươi triệu đồng? Kể cho em và mọi người ở phần bình luận nhé.'}]
META = {'NONG1711A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Tin nóng trong ngày', 'ngay': '2026-11-17', 'gio_goi_y': '19:30', 'gio': '19:30', 'nhac': 'lofi', 'tieu_de': 'Lãi Suất Tiết Kiệm 0% Ở SCB: Gửi 200 Triệu 6 Tháng Nhận 0 Đồng – Tiền Gửi Có Còn An Toàn?', 'title': 'Lãi Suất Tiết Kiệm 0% Ở SCB: Gửi 200 Triệu 6 Tháng Nhận 0 Đồng – Tiền Gửi Có Còn An Toàn?', 'mo_ta': 'NÓNG: từ 16/11/2026, SCB đưa lãi suất tiết kiệm online về 0%/năm cho các kỳ hạn từ 31 ngày đến 36 tháng; tại quầy, khách cá nhân gửi mới kỳ hạn dưới 12 tháng cũng 0%. Vì sao một ngân hàng không trả lãi, tiền gửi có còn an toàn, lần trước tháng 10/2022 ai thiệt, bảo hiểm tiền gửi 350 triệu bảo vệ đến đâu, và phép thử cho cuốn sổ của anh chị.\n\nNguồn số liệu:\n• Dân trí 16/11/2026: biểu lãi SCB từ 16/11 – online 0%/năm kỳ hạn 31 ngày, 1, 3, 6, 12, 36 tháng (3 cách lĩnh lãi); tiết kiệm thường khách cá nhân gửi mới 0%; kỳ hạn 12 tháng 3,7%/năm, 13 tháng 8,7%/năm (lãi cuối kỳ, biểu trước đó); lần điều chỉnh mạnh thứ hai trong 1 tháng; kiểm soát đặc biệt từ 2022; chuyển tiền nhanh tối đa 20 triệu/ngày; khoảng 240 điểm giao dịch trước đây, ngày 3/11 còn 8 điểm tại 6 tỉnh, thành; lãi online phổ biến ở ngân hàng khác: 6 tháng 4,15–6,9%, 12 tháng 6–7%\n• Người Quan Sát 16/11/2026: kỳ hạn 12 và 13 tháng theo biểu 26/10, SCB chưa công bố biểu thay thế; VPBank online dưới 10 tỷ kỳ hạn 6–11 tháng 6,6%/năm; VPBank là ngân hàng thứ 5 giảm lãi huy động hơn một lần từ 18/10\n• MotTheGioi 16/11/2026: lãi cao nhất SCB trước 2024 8,5–9,5%; 2024 đến trước 10/2026 3,9%; cuối 10/2026 0,7%; từ 16/11 0% (trừ 12–13 tháng); trường hợp cá biệt, không phải xu hướng chung\n• Vietstock 17/11/2026: lãi tiết kiệm giảm 0,5–2%/năm, huy động qua trái phiếu ngân hàng 8–10%/năm\n• CafeF 22/8/2026: ngày 30/6/2026 NHNN trình Thủ tướng phương án xử lý tài sản thu hồi nợ của SCB\n• VnEconomy 8/10/2022: NHNN khẳng định quyền lợi người gửi tiền SCB được bảo đảm, rút trước hạn sẽ mất lãi; báo chí 15/10/2022 dẫn SCB: ngày 12/10/2022 khách gửi lại gần 6.000 tỷ đồng trong 1 ngày (ngày trước hơn 1.600 tỷ)\n• VietnamPlus 20/7/2026, Báo Đầu tư: Thông tư 05/2026/TT-NHNN – hạn mức chi trả bảo hiểm tiền gửi tối đa 350 triệu đồng (cũ 125 triệu) từ 13/7/2026, tính trên tổng gốc và lãi của một người tại một tổ chức\n• Tự tính: 200 triệu, 6 tháng – lãi 0% = 0 đồng; 0,7% ≈ 700 nghìn; 6,6% ≈ 6,6 triệu; kỳ hạn 12 tháng 3,7% ≈ 7,4 triệu sau 1 năm; 200 triệu ÷ 20 triệu/ngày = 10 ngày; 240 ÷ 8 = 30; 350 ÷ 125 = 2,8 lần\n\nGửi tiết kiệm an toàn chưa chắc lãi thực – lạm phát và sức mua: https://chungkhoanhuynguyen.com/hoc/gui-tiet-kiem-an-toan-chua-chac-lai-thuc-lam-phat-va-suc-mua-sau-10.html\nLãi suất giảm ở 46 ngân hàng – ai được giảm: https://chungkhoanhuynguyen.com/hoc/lai-suat-giam-o-46-ngan-hang-ai-duoc-giam-2-vi-sao-khoan-vay-mua-nha.html\nCần trao đổi riêng về kế hoạch tài chính: Zalo 0365.188.286\n\nNhân vật cô Hạnh, con gái, anh Toàn, bác Tư là hư cấu; số liệu là thật theo nguồn trên. Lãi suất có thể thay đổi, anh chị kiểm tra trực tiếp với ngân hàng.\nChia sẻ góc nhìn, không phải khuyến nghị.', 'tags': ['lãi suất tiết kiệm', 'lãi suất 0%', 'SCB', 'lãi suất ngân hàng hôm nay', 'gửi tiết kiệm', 'bảo hiểm tiền gửi', '350 triệu', 'tiền gửi an toàn', 'tin nóng tài chính', 'lãi suất tháng 11'], 'bia_hook': ['LÃI SUẤT 0%', 'TỪ 16/11'], 'badge': 'TIỀN GỬI CÒN AN TOÀN?', 'bia_anh': 'Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'bia_hook_b': ['GỬI 200 TRIỆU', 'LÃI 0 ĐỒNG'], 'badge_b': 'NƠI KHÁC: 6,6 TRIỆU', 'bia_hook_c': ['TỪ 9,5%', 'VỀ 0%???'], 'badge_c': 'BẢO HIỂM TỐI ĐA 350 TR', 'reel_hook': 'LÃI SUẤT TIẾT KIỆM 0%|TIỀN GỬI CÒN AN TOÀN???', 'fb_post': 'Một ngân hàng đưa lãi suất tiết kiệm về 0% 😳\n\n👉 Gửi 200 triệu 6 tháng: 0 đồng tiền lãi\n👉 Nơi khác cùng kỳ hạn: khoảng 6,6 triệu\n👉 Bảo hiểm tiền gửi nay tối đa 350 triệu mỗi người, mỗi ngân hàng\n\nTiền gửi của anh chị ở 1 nơi đang dưới hay trên 350 triệu?\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Biểu lãi suất mới nói gì?', 'Chương 2 – Vì sao ngân hàng không trả lãi?', 'Chương 3 – Lần trước là tháng 10/2022', 'Chương 4 – Lưới an toàn 350 triệu', 'Chương 5 – Ba con đường cho cuốn sổ', 'Chương 6 – Phép thử cho sổ tiết kiệm', 'Kết – Tin nhắn cuối ngày']}}
